LAYER
  NAME "oficinas_cz"
  STATUS ON
  TYPE POINT
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, clv_cz, nom_cz, the_geom FROM ivea.oficinas_cz) AS t1 USING UNIQUE gid USING SRID=900913"
